"""
Migration de dados para flag MatriculaDiario.prova_final_pendente
Seleciona matrícula que têm prova pendente e atualiza a flag.


Para isso, alguns métodos de MatriculaDiario foram replicados abaixo,
de acordo com a regra de negócio na época da criação desta migração.
"""


def is_em_prova_final(matricula_diario):
    if realizou_todas_avaliacoes_regulares(matricula_diario):
        return (
            not is_reprovado_direto(matricula_diario)
            and not is_aprovado_sem_prova_final(matricula_diario)
            and not realizou_avaliacao_final(matricula_diario)
        )
    return False


def realizou_todas_avaliacoes_regulares(md):
    qtd_avaliacoes = md.diario.componente_curricular.qtd_avaliacoes
    if qtd_avaliacoes == 0:
        return True
    elif qtd_avaliacoes == 1:
        return md.nota_1 is not None
    elif qtd_avaliacoes == 2:
        return md.nota_1 is not None and md.nota_2 is not None
    elif qtd_avaliacoes == 4:
        return md.nota_1 is not None and md.nota_2 is not None and md.nota_3 is not None and md.nota_4 is not None
    return False


def is_reprovado_direto(md):
    return get_media_disciplina(md) < md.matricula_periodo.aluno.matriz.estrutura.media_evitar_reprovacao_direta


def is_aprovado_sem_prova_final(md):
    if md.diario.componente_curricular.qtd_avaliacoes == 0:
        return True
    else:
        return get_media_disciplina(md) >= md.matricula_periodo.aluno.matriz.estrutura.media_aprovacao_sem_prova_final


def realizou_avaliacao_final(md):
    return md.nota_final is not None


def get_media_disciplina(md):
    media_disciplina = 0
    qtd_avaliacoes = md.diario.componente_curricular.qtd_avaliacoes

    # a média da disciplina deve retonar None caso alguma das notas esperadas não tenha sido registrada
    if qtd_avaliacoes > 0:
        if md.nota_1 is None:
            return None
    if qtd_avaliacoes > 1:
        if md.nota_2 is None:
            return None
    if qtd_avaliacoes > 2:
        if md.nota_3 is None or md.nota_4 is None:
            return None

    if qtd_avaliacoes == 1:
        return md.nota_1 or 0
    elif qtd_avaliacoes == 2:
        return int(round((2 * (md.nota_1 or 0) + 3 * (md.nota_2 or 0)) / float(5)))
    elif qtd_avaliacoes == 4:
        return int(round(
            (2 * (md.nota_1 or 0) + 2 * (md.nota_2 or 0) + 3 * (md.nota_3 or 0) + 3 * (md.nota_4 or 0)) / float(10)))

    return media_disciplina


