def atualizar_matriculasdiario_existentes(apps, schema_editor):
    MatriculaDiario = apps.get_model('edu', 'MatriculaDiario')

    # De edu.models.MatriculaDiario:
    # SITUACAO_CURSANDO = 1
    # SITUACAO_PROVA_FINAL = 4
    matriculas = MatriculaDiario.objects.filter(
        situacao__in=[1, 4],
        diario__calendario_academico__data_fechamento_periodo__lt=datetime.date.today(),
    )

    ids_md_prova_final_pendente = list()
    for matricula in matriculas.all():
        if is_em_prova_final(matricula) and not realizou_avaliacao_final(matricula):
            ids_md_prova_final_pendente.append(matricula.pk)

    MatriculaDiario.objects.filter(pk__in=ids_md_prova_final_pendente).update(prova_final_pendente=True)


def desfazer_atualizacoes(apps, schema_editor):
    MatriculaDiario = apps.get_model('edu', 'MatriculaDiario')
    MatriculaDiario.objects.filter(prova_final_pendente=True).update(prova_final_pendente=False)


